type User { name: String!  posts: [Post!]! }
type Post { title: String! }

the title of post 2 fails:
  title  is String!   -> post 2 cannot be null
  [Post!]!            -> the list cannot hold a null item, so it cannot be null
  User.posts is !     -> posts cannot be null
  user(id) is nullable-> user becomes null

result:  { "data": { "user": null }, "errors": [ ... ] }

message Book {
	string title = 1;
	int32 year = 2;
}
service Library {
	rpc Get (BookId) returns (Book);                 // unary
	rpc Upload (stream Chunk) returns (Summary);     // client streaming
}
